import{_ as t,o,c as a,ak as s}from"./chunks/framework.sV-XtlWr.js";const i="/screenshots/execution-locators.png",g=JSON.parse('{"title":"Who uses a locator","description":"","frontmatter":{"title":"Who uses a locator","lang":"en-US"},"headers":[],"relativePath":"features/locator-usage.md","filePath":"features/locator-usage.md","lastUpdated":1790334937000}'),n={name:"features/locator-usage.md"};function r(c,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="who-uses-a-locator" tabindex="-1">Who uses a locator <a class="header-anchor" href="#who-uses-a-locator" aria-label="Permalink to &quot;Who uses a locator&quot;">​</a></h1><p>Before you change an element — rename a label, remove a <code>data-testid</code>, replace a <code>&lt;select&gt;</code> with an autocomplete — you can see which tests reach it and from which lines.</p><p>Playwright reports the full locator chain on every locator step: <code>getByRole(&#39;form&#39;, { name: &#39;Shipping&#39; }).getByLabel(&#39;Country&#39;)</code>, not only the last call. Piwi already stores those steps for every execution, passing ones included, so it indexes each chain with the action that used it (<code>Select option</code>, <code>Expect toHaveValue</code>, …) and the call site (<code>file:line:col</code>, often a page-object method). Nothing extra is captured while tests run: the index works with the reporter alone, and with <a href="./locator-healing.html">locator healing</a> turned off.</p><h2 id="the-locators-tab" tabindex="-1">The Locators tab <a class="header-anchor" href="#the-locators-tab" aria-label="Permalink to &quot;The Locators tab&quot;">​</a></h2><p>An execution&#39;s evidence card has a <strong>Locators</strong> tab listing every locator the test used, in order, with the action and the call site. The count beside each one is how many tests in the project use the same chain. A test case&#39;s page shows the same list for its latest execution.</p><figure><img src="'+i+'" alt="The Locators tab of an execution: each locator the test used, numbered in step order, with its action above it and a button giving how many tests use the same chain"><figcaption>Every locator an execution used, in step order.</figcaption></figure><p>Opening a count answers <strong>Who uses this?</strong> in three ways:</p><ul><li><strong>This locator</strong> — tests whose steps used this exact chain.</li><li><strong>Same target</strong> — chains ending on the same call inside any container, so <code>getByLabel(&#39;Country&#39;)</code> on its own and inside the shipping form both count.</li><li><strong>Inside its container</strong> — every chain that searches inside one of the chain&#39;s containers. Changing the container itself (removing a wrapper, renaming a form) reaches all of them, even when no test targets the container directly.</li></ul><p>Call sites shared by the most tests come first: a page-object line used by five tests is one fix for all five. <strong>Run these tests</strong> turns the list into a <code>npx playwright test</code> command through the same materialization as <a href="/guide/test-selection.html">test selection</a>.</p><h2 id="requirements-and-limits" tabindex="-1">Requirements and limits <a class="header-anchor" href="#requirements-and-limits" aria-label="Permalink to &quot;Requirements and limits&quot;">​</a></h2><ul><li><strong>Playwright 1.61 or later</strong>, with step collection on (<code>collectPerformanceMetrics</code>, the default). Playwright 1.63 puts the chain in each step&#39;s parameters; 1.61 and 1.62 print it in the step title, which Piwi reads the same way.</li><li><strong>Getter calls are not reported.</strong> Playwright hides <code>textContent()</code>, <code>inputValue()</code>, <code>isVisible()</code> and similar calls from reporters, so a locator used only through them is not in the index.</li><li><strong>Long and described chains.</strong> Piwi keeps the first 500 steps of an execution (<code>PIWI_INGEST_MAX_STEPS</code>) and the first 200 characters of each step parameter (<code>PIWI_INGEST_MAX_STEP_PARAM_VALUE_CHARS</code>), and <code>locator.describe()</code> replaces the chain with its description. Chains cut short or described are skipped.</li><li><strong>Matching is by chain text.</strong> Two different chains that happen to resolve to the same element count separately. The counts tell you where to look, not that a test will break.</li><li><strong>The index fills itself.</strong> New runs are indexed as they arrive. When the server starts, it indexes each project&#39;s stored history once: for every test and Playwright project, the latest passed execution, or the latest one when none passed. To rebuild it later, call the rebuild endpoint: see the <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API docs</a>, or <code>/docs</code> on your own instance.</li></ul>',11)])])}const m=t(n,[["render",r]]);export{g as __pageData,m as default};
